{$ param eyebrow label="Eyebrow" default="First things first!" description="Small text above the title." $}
{$ param title label="Title" default="Create a Free SciStarter Account" description="Main heading." $}
{$ param primary_label label="Primary Label" default="Sign Up" description="Primary button text." $}
{$ param primary_href label="Primary URL" default="/signup" description="Primary destination." $}
{$ param secondary_label label="Secondary Label" default="" description="Optional second button text." $}
{$ param secondary_href label="Secondary URL" default="/signup" description="Optional second button destination." $}
{$ param bg_class label="Background Classes" default="bg-girlscout-alpha" description="Tailwind background color class." $}
{$ param btn_class label="Button Classes" default="bg-girlscout hover:bg-girlscout-hover text-white" description="Tailwind classes applied to the buttons." $}

<div class="{$= bg_class $} flex flex-col p-4 items-center rounded-lg mb-8">
  {$ if eyebrow $}<h3 class="font-bold ss-xsmall text-center">{$= eyebrow $}</h3>{$ /if $}
  <h2 class="font-bold ss-normal mb-4 text-center">{$= title $}</h2>
  <a href="{$= primary_href $}" class="btn uppercase font-bold w-auto min-w-[165px] text-center mb-4 {$= btn_class $}">{$= primary_label $}</a>
  {$ if secondary_label $}<a href="{$= secondary_href $}" class="btn uppercase font-bold w-auto min-w-[165px] text-center {$= btn_class $}">{$= secondary_label $}</a>{$ /if $}
</div>
